Lemma land_m1_l : forall a, 0 <= a < 2^64 -> Z.land 18446744073709551615 a = a.
Proof. intros a Ha. change 18446744073709551615 with (Z.ones 64). rewrite Z.land_comm, Z.land_ones by lia. apply Z.mod_small. lia. Qed.

